sealed class IdentityApiException: kotlin.Exception() {

    class InvalidInput(
        ) : IdentityApiException() {
        override val message
            get() = ""
    }

    class InvalidOptions(
        ) : IdentityApiException() {
        override val message
            get() = ""
    }

    class Submission(

        val `reason`: IdentitySubmissionFailure
        ) : IdentityApiException() {
        override val message
            get() = "reason=${ `reason` }"
    }

    class Authority(

        val `reason`: IdentityFault
        ) : IdentityApiException() {
        override val message
            get() = "reason=${ `reason` }"
    }

    class Storage(

        val `reason`: IdentityStorageFailure
        ) : IdentityApiException() {
        override val message
            get() = "reason=${ `reason` }"
    }

    class Creation(

        val `reason`: IdentityCreationFailure
        ) : IdentityApiException() {
        override val message
            get() = "reason=${ `reason` }"
    }

    class Runtime(

        val `reason`: IdentityRuntimeFailure
        ) : IdentityApiException() {
        override val message
            get() = "reason=${ `reason` }"
    }

    class Driver(

        val `reason`: IdentityServiceFailure
        ) : IdentityApiException() {
        override val message
            get() = "reason=${ `reason` }"
